NIGHT_LOADED({"seed":1021,"generated_at":"2026-10-21T06:00:00Z","chain":[1,3,4,2,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":6,"drawers":[{"id":"1-1","type":"P2","difficulty":3.0068,"rank":0.0948,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV000604","role":"target","render":{"description":"Dringend advies om een brandverzekering af te sluiten, want iemand heeft het huis in brand zien staan. Een tijd later brandt het huis af.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/42967","original":"[4.]\nMijn opa kwam ook eens bij buurman Scheper. \"Hest dien hoes in de brandkaaste Beernd?\"\n\"Nee,\" zei Beernd.\n'n Paor dagen later opa er weer heen.\n\"Beernd, hest 't hoes in de brandkaaste?\"\n\"Nee, nog nich.\"\n\"Dou hum d'r doadeluk in, want ik heb 't branden zain.\"\nEen paar maanden later, daor ging 't huis.","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV005903","role":"helper","render":{"description":"Bij afbranden van zijn boerderij vertelt man dat hij lang van tevoren heeft gezien dat het huis in brand staat, maar er over heeft gezwegen.","place":"Wessingtange","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43264","original":"Veurloop.\nJoarn leden is hier brand west. Ik huilp de boer mit alles. De man stön aal man stil te kiekn en zee:“Nôn brand e ja.”\nIk vruig:“Hou komst door bie, wat betaikent dat?”\n“t Is wol al tien joar leden”, zee e dou, “op n oavend kwam k bie hoes en dou stôn alles in lichtelaaie. k Heb dr nooit over proot, mit ganaine, man nôn brand e ja.”","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9175,7.14444]},{"id":"c3","story_id":"WEV007406","role":"helper","render":{"description":"Lichten worden gezien als voorloop van brand.","place":"Musselkanaal","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44126","original":"Lichten zaggen ze vrouger voak. \"dr brandt weer wat\", zeden ze, zel wel weer gauw n huus aan goan. Dat geleuf was algemain.","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9325,7.01528]},{"id":"c4","story_id":"WEV013008","role":"helper","render":{"description":"Voorspelling dat alle witte huizen afbranden komt uit, alleen witte kerk staat er nog.","place":"Bourtange","prov":"Gr.","year":1966,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44092","original":"Oal vrouw K. zag vrouger ale widde huuzn in Boertange brannen.\n“Zai brant aal op”, zee ze. En t oal hef nog gliek kreegn ook. Allaind de widde kerke stait dr nog.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.01,7.19028]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessingtange.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.1418,"rank":0.2835,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ070902","role":"member","render":{"description":"Mensen zagen eens een boerderij in brand staan. Maar toen ze dichterbij kwamen, was er niets aan de hand. Later is de boerderij echt afgebrand.","place":"Augustinusga","prov":"Fr.","year":1969,"code":"SINSAG 0491","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27979","original":"Myn wiif fortelde wolris dat to Sybrandahûs - tusken Dokkum en Rinsumageast - seagen lju yn 'e nacht in boereplaets yn 'e brân. Hja hearden allerhande lûden en stemmen fan minsken. Sy gongen der hinne, mar der wie neat.\nLetter is dy plaets troch de tonger opbrând.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"CJ088406","role":"member","render":{"description":"Een man zag eens een boerderij in brand staan, maar toen hij dichterbij kwam, bleek er niets aan de hand te zijn. Later is het bedrijf toch nog afgebrand.","place":"Harkema","prov":"Fr.","year":1971,"code":"SINSAG 0491","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33288","original":"yn 'e brân. 't Wie by de earste bocht as men gyng fan 'e brêge fan 'e Harkema nei Surhústerfean. Mar doe't omke der by kom, brânde 't net.\nLetter is dat spul ôfbrând.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"KEMP295","role":"intruder","render":{"description":"Een jongen wordt van het weerwolven verlost, doordat zijn pels verbrand raakt. Zijn vrienden hebben hem hierbij onbedoeld geholpen.","place":"Broek","prov":"L.","year":1925,"code":"SINSAG 0824","initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/43420","original":"De weerwolf verlost\n\nTe Blitterswijk woonde een jonge man die de naam had des nachts uit weerwolven te gaan. Enige vrienden wilden echter wel eens bij die gedaanteverwiseling tegenwoordig zijn. Zij gingen daarom een avond naar zijn huis en zetten zich om de haard. Het ging op middernacht aan en daar niemand sprak van naar huis gaan, zweette de weerwolf water en bloed van benauwdheid. Hij wilde de deur uit, maar zijn kameraden beletten hem dit en hielden hem stevig vast.\nToen het middernacht sloeg, viel opeens een groot wolfsvel uit de schoorsteen in het vuur. De weerwolf begon te schreeuwen als een bezetene en stelde zich aan als een duivel. …","lang":"Standaardnederlands","front":"original"},"home":"cab:3"},{"id":"c4","story_id":"CJ037801","role":"member","render":{"description":"Een jongen en een meisje zagen vanuit de verte eens een brand, maar toen ze dichterbij kwamen, was er helemaal geen brand. Een jaar later is er op die plek toch brand uit gebroken.","place":"Kollum","prov":"Fr.","year":1968,"code":"SINSAG 0491","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23086","original":"It is jierren lyn. Ik en myn feint kommen us fan Sweagerfean. Wy moesten nei de Triemen ta. Wy roannen de Úlke-loane del by Swagerfean. Doe't wy sahwat midden op 'e loane wienen, en oer de feart seagen, seinen wy: \"Sjoch, dêr is brân!\"\nDêr woenen wy hinne en sa kommen wy op 'e Trekwei. Mar dêr wie neat to sjen. Alles wie tsjuster.\nIn jier nei dy tiid briek dêr brân út op in pleats, krekt op datselde plak, dêr't wy de brân sjoen hienen.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Broek hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":3},"on_success":{"trail_note":0,"unlock_cabinet":3,"stack":["c1","c2","c4"]}},{"id":"1-3","type":"R1","difficulty":1.0771,"rank":0.0042,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ031107","role":"omen","render":{"description":"Als er een spiegel naar beneden valt, sterft er binnen zes weken iemand.","place":"Twijzelerheide","prov":"Fr.","year":1967,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21986","original":"As in spegel delkomt, komt der binnen seis wiken in sippe deaden.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CBAK0041","role":"omen","render":{"description":"Voorspelling dat een kind niet oud zal worden. Het kind sterft inderdaad op zes-jarige leeftijd.","place":"Broek in Waterland","prov":"N.-H.","year":1899,"code":"SINSAG 0489","initials":"C.B.","url":"https://www.verhalenbank.nl/items/show/8638","original":"Grietje Holleman heeft tegen een broertje van een Broeker dame gezegd dat hij niet oud zou worden. Op zes-jarige leeftijd is hij overleden.","lang":"Standaardnederlands","front":"description"},"home":"1-3"},{"id":"c3","story_id":"WEV013104","role":"omen","render":{"description":"Lijk dat zondag overstaat betekent binnen zes weken weer een sterfgeval .","place":"Bellingwolde","prov":"Gr.","year":1966,"code":"SINSAG 0486","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44380","original":"n Volksgeleuf was wieder, dat as ain liek n zundag overstun, dat er den binnen zes weekn weer ['n] staarfgeval komen zol.","lang":"Gronings","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","6 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":6},"on_success":{"chime":6,"digit":{"value":6,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":3,"drawers":[{"id":"2-1","type":"P5","difficulty":0.6258,"rank":0.0,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"HOL000404","role":"variant","render":{"description":"Zien van witte juffer; met wit laken om spelen voor witte juffer.","place":"Ingen","prov":"Gld.","year":1962,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/209537","original":"Witte vrouwen . Bij de pas (aanplant van wilgen of populieren met onderhout van elzen en essen) (lag dicht bij de woning van de zegslieden) zag men soms een witte gedaante lopen. Maar sommigen geloofden niet aan de witte juffer, zo werd Han Briene er van verdacht, dat hij soms de kinderen bang wilde maken door voor witte juffer te spelen (hij deed zich dan een laken om) Enige jongens wilden met Jas Gaosbeek, een niet volwaardige zoon van een bakker, een grap uithalen. Zij sloegen zich lakens om en gingen wandelen op een plaats, waar Jas passeren moest. Deze ging er echter niet voor door, maar begon de \"juffer\", die hij het eerst te pakken kreeg af te ranselen. De andere jongens sloegen toen op de vlucht","lang":"Standaardnederlands","front":"original"},"home":"2-1"},{"id":"c2","story_id":"HOL002208","role":"variant","render":{"description":"'s Avonds stok met krant aanzien voor witte juffer.","place":"Ochten","prov":"Gld.","year":1963,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210065","original":"Er moet een witte juffer gelopen hebben op het Zand (fruitteeltbedrijf) bij het witte hek (dit stond op de weg, die tussen twee kolken doorloopt. Keuken, hij was toen 18 jaar, ging eens met een kameraad naar Eldik (buurtschap) om een vriend te bezoeken. Deze bleek niet thuis. Op de dijk op de plaats waar beneden het witte hek stond, was een stok met krant er om gezet, als teken voor de castreur dat er \"keujes\" moesten gesneden worden. Janus stapte tegen deze stok aan, deze ging heen en weer, de kameraad beweerde, dat hij een witte juffer had gezien en was van dit idee, ook de volgende dag, niet af te brengen","lang":"Standaardnederlands","front":"original"},"home":"2-1"},{"id":"c3","story_id":"HOL002604","role":"variant","render":{"description":"Witte juffer die de weg vraagt, gooit hoed vol geld, en verdwijnt.","place":"Tiel","prov":"Gld.","year":1964,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210163","original":"Berend, den dakuil (een Van Uden) smeerde de daken van binnen aan met kalk, vandaar dat hij deze bijnaam kreeg. Eens liep Berend op de Grotebrugse grintweg bij de Twaalf Apostelen (straatje) toen een witte juffer hem de weg vroeg naar het veer. Berend zei haar die en nadat hij dit gedaan had, gooide zij hem de hoed vol met \"Berliner daolder\". Driemaal was Berend dit overkomen. Bij het veer gekomen wilde Berend haar bedanken, maar hij kreeg geen kans daartoe: zij was verdwenen.","lang":"Standaardnederlands","front":"original"},"home":"2-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Gelderland werd een voorwerp gezien: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"2-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1962.","Op die kaart staat een voorwerp. Welk?"],"lock":{"kind":"word","salt":"222e7416a6a8c788","accepted_hashes":["2af116d37d50853dea5c869a83de9ccbc58d8e9a636c025af7c608a95db30646","2d8823ae3e856e5f8253994ed8d428e34c60faaf31aac105751059ab42aeff6b","2fd0ebda56eec11c9eea4088c8e7b9230f23ee9f6cf05e5ba7181cfc7d1ab905","be2f593217f9aae59c1ace2aa3b262a042114c2184983fc9784ce9b9b0f5cdfa","ddbc659915458f200c05196310526877d44ddfadfe8db1d70116703a7809cd00"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"2-2","type":"P3","difficulty":1.4374,"rank":1.1941,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ103913","role":"member","render":{"description":"Man dacht op een avond in een vrouw die hem tegemoet kwam, zijn nichtje te zien. Hij werd echter opgetild en weggesmeten, waarna de vrouw wegzweefde.","place":"Drogeham","prov":"Fr.","year":1973,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37327","original":"It gebeurde op 'e Ikkers op in joun dat Harm Hamstra bûtendoar kaem en in frommeske seach. Hy miende dat it syn nichtsje wie, in jongfaem fan sa'n tweintich jier: Wytske Hamstra, dy't letter troude mei Elle Wijma fan Eastemar. Hja kaem him yn 'e mjitte.\nHy sei: \"Bistû dêr noch, Wytske?\"\nMar dyselde sei neat werom. Ynpleats dêrfan wied er opnom woarn en in ein fuortsmiten en dat frommeske wie swevend fuortrekke.\nOp 'e weromreis kom er wer by ús tolânne. 't Ljocht wie by ús noch op. Doe hat ús heit him dat út brocht hwant hy doarst dêr net wer allinne lâns.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"CJ103307","role":"member","render":{"description":"Een man zag eens een vrouw in het wit aankomen. Omdat hij dacht haar te kennen, wilde hij haar groeten, maar toen hij dichterbij kwam ging ze in rook op.","place":"Drogeham","prov":"Fr.","year":1973,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37235","original":"In man fan Droegeham (it wie Hindrik Hoeksma sels) seach op in joun op 'e Ikkers in frommes yn 't wyt oankommen.\nHy miende dat er har wol koe en soe har groetsje. Mar doe't er flakby wie, wie se samar ynienen fuort troch in daem. Der wie neat mear fan har to sjen.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"BIJLSMA000103","role":"member","render":{"description":"Man ziet 's morgens vroeg een witte vrouw.","place":"Hemelum","prov":"Fr.","year":1965,"code":null,"initials":"T.B.","url":"https://www.verhalenbank.nl/items/show/130174","original":"Oer de Lytse Maren sjocht men op ’e eftergroun de Wite Burch. Dêr seach men eren wite wiven. In man fan Himmelom, Melchers hjitte er, gie op in moarn ier en bitiid to ikeboskjen, en seach dêr yn in iepen plak tsjin de Wite Burch oan in wyt wiif omdoarmjen.","lang":"Fries","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"CJ053715","role":"intruder","render":{"description":"Een man heeft eens een ontmoeting gehad. Hij werd ruw door de persoon gesmeten.","place":"Boornbergum","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25414","original":"Alde Rinse de Wind fan 'e Harkema hat ek us in ûntmoeting hawn. Dy waerd dêrby ek smiten.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:5"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Boornbergum hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c2","c3"]}},{"id":"2-3","type":"R2","difficulty":1.1119,"rank":0.9153,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"CJ006015","role":"card","render":{"description":"In Den Andel staat een spookschuur. Er is wel een vrouw voor het raam gezien met een hoofd zo wit als krijgt en het haar slap eromheen.","place":"Buitenpost","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/16534","original":"Yn Den Andel wie ek in spûkskuorre. De minsken dy't op dy pleats wennen, woarden sa binaud, dat se der wei gong binne. Der stienen allegear beammen om dy plaets hinne. Guon ha dêr wol in frommes foar it glês stean sjoen mei in holle sa wyt as kryt, en 't hier der sleau om hinne.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c2","story_id":"LYST282","role":"card","render":{"description":"Een boerenknecht heeft verkering met een boerenmeid. Omdat hij haar ervan verdenkt te kunnen toveren, wil hij het uitmaken. Het meisje vraagt hem echter de volgende avond naar de schaapskooi te komen. De knecht stemt in. Als hij bij de schaapskooi staat, vliegt er opeens een witte gedaante voorbij. Vlak daarna verschijnt de boerenmeid, die bij hoog en laag beweert dat zij de witte gedaante niet geweest is. De knecht gelooft haar niet.","place":"Ede","prov":"Gld.","year":1937,"code":"SINSAG 0310","initials":"L.C.S.","url":"https://www.verhalenbank.nl/items/show/13626","original":"Witte Wieven\nDe Witte Wieven hadden hun \"vertoonplaats\" meest op het Hooge Dennenboschje, aan de weg naar Veenendaal, 15 min. buiten het dorp. Soms reden ze op schimmels rond. Eens had een boerenknecht een vrijage met een boerenmeid. Daar ze echter tooveren kon, wilde hij van haar af. Zij zei echter tegen hem: \"Je zult morgen bij de schaapskooi komen, om 8 uur 's avonds. Dit deed hij. Op eens vloog een witte gedaante op een schimmel hem voorbij en verdween in de schapenstal. Het meisje kwam plots bij hem en zei: \"Heb je dat gezien? Dat was ik niet hoor.\" Maar hij dacht er het zijne van.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c3","story_id":"KOOIJMAN2497","role":"card","render":{"description":"Er wandelde 's avonds een juffrouw op en neer om de mensen opmerkzaam te maken dat een boer een weipaal had verzet. En daardoor had die boer er een stuk land bijgekregen, wat niet van hem was.","place":"Raamsdonk","prov":"N.-Br.","year":1963,"code":"SINSAG 0310","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/128006","original":"In Waspik is de Juffrouwsteeg. Die is daar nog steeds, die heet nog altijd zo. Het verhaal ging, daar wandelde 's avonds een juffrouw op en neer om de mensen opmerkzaam te maken dat een boer een weipaal had verzet. En daardoor had die boer er een stuk land bijgekregen, wat niet van hem was. Die juffrouw zei dan: \"Hier heb je gestaan en zal je nooit meer komen\"*.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c4","story_id":"CJ000411","role":"sill","render":{"description":"Drie rondspokende naakte vrouwen zitten een man achterna die zo hard moet lopen dat hij verschrikkelijk moet zweten.","place":"Nijega","prov":"Fr.","year":1965,"code":"SINSAG 0161","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/11550","stain":"Drie"},"home":"2-3"},{"id":"c5","story_id":"CJ007910","role":"card","render":{"description":"Bij Hattum de Vries in het laantje spookte 's nachts altijd een wit wijf. De mensen durfden er 's nachts niet te komen, want ze werden er door dat witte wijf aan de kant gedreven naar het meertje toe. Zonder dat ze zelf iets deden, kwamen ze in het meertje terecht.","place":"Oudega","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17053","original":"By Hattum de Vries yn it loantsje spoeke nachts altyd in wyt wiif. De minsken doarsten dêr nachts noait to kommen. Hwant sy waerden dêr stadich troch dat wite wiif oan kant treaun nei de dobbe ta. Sûnder dat se it sels fornamen kommen se yn 'e dobbe torjochte.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c6","story_id":"CJ006515","role":"card","render":{"description":"Op de Lytse Wei spoken twee witte vrouwen. In het donker gaat men er niet langs.","place":"Harkema","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/16867","original":"Op 'e Lytse Wei spoeken twa wite wiven. Yn 't tsjuster doarsten se dêr net lâns.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een N.","Nijega. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c4","object":"window","text":"Nijega"},"on_success":{"digit":{"value":3,"card":"c4","word":"Drie","stained":"c4"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P4","difficulty":1.6872,"rank":0.6552,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"GENDT028","role":"top","render":{"description":"Een van de leden van een kaartclub moet op sommige avonden opeens weg en de anderen verdenken hem ervan dat hij een","place":"Gendt","prov":"Gld.","year":1965,"code":"SINSAG 0824","initials":"M.H.D.","url":"https://www.verhalenbank.nl/items/show/49658","half":"top"},"home":"3-1"},{"id":"c2","story_id":"KEMP298","role":"distractor","render":{"description":"Hij stuurt hem weg voor een dag en hij en zijn knechten ontdekken in een holle wilg een wolvenvel. Ze steken het thuis in brand. De scheper keert vervolgens in razend tempo terug en wil zijn vel teruggrijpen. Als dat niet lukt, vlucht de scheper naar de holle boom en is nooit meer teruggezien.","half":"bottom","code":"SINSAG 0824"},"home":"3-1"},{"id":"c3","story_id":"CJ052012","role":"distractor","render":{"description":"Haar man moet als weerwolf regelmatig ergens in bijten. Rood garen prijkt in zijn kiezen. Vooral in rode wol zetten weerwolven graag hun tanden.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"},{"id":"c4","story_id":"GENDT030","role":"distractor","render":{"description":"Hij ziet de weerwolf op de afgesproken plek, slaat de bijl door het brood en vervolgens tegen de arm van de weerwolf. De weerwolf veranderd weer in een mens en is bevrijd.","half":"bottom","code":"SINSAG 0822"},"home":"3-1"},{"id":"c5","story_id":"CJ095508","role":"distractor","render":{"description":"Geef iets, dat ik er op kan.\"\" Ze geeft hem een doek en hij verscheurt die met zijn tanden; de rafels hingen uit zijn muil. Had hij niets gekregen, dan had hij zijn meisje verscheurd.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"},{"id":"c6","story_id":"LYST017","role":"distractor","render":{"description":"De pastoor raadt aan om het in de boom gevonden vel te verbranden. Pastoor spreekt gebeden uit, de man moet worden vastgehouden omdat hij het vel uit het vuur wil halen. Na het verbranden van het vel is de man van de duivel verlost, en hoeft geen weerwolf meer te zijn.","half":"bottom","code":"SINSAG 0824"},"home":"3-1"},{"id":"c7","story_id":"BROUWERS002507","role":"distractor","render":{"description":"Weerwolf komt op meisje af, dat het doosje naar hem gooit. Weerwolf verdwijnt, jongen komt terug.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"},{"id":"c8","story_id":"DYKFRIES2219","role":"distractor","render":{"description":"Meestal is de weerwolf woedend, vooral als hij iets roods ziet. Soms kan hij daardoor verwond raken of zijn er mensen de hem slaan. Hiervan kan hij een teken op zijn lichaam aan over houden en dit kan invloed uitoefenen op zijn karakter. Het kan dat hij in het vervolg als een <<rare vent>> wordt gezien.","half":"bottom","code":"SINSAG 0804"},"home":"3-1"},{"id":"c9","story_id":"ZEEUW184","role":"distractor","render":{"description":"Ze zagen duidelijk dat hij een stuk van een boezeroen tusschen de tanden had.Een poosje later kwam de weerwolf, een boerenarbeider uit Kloetinge, hen voorbij op weg naar zijn werk.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"},{"id":"c10","story_id":"VVUNL315","role":"distractor","render":{"description":"Tis de smid sleept de rugplakker, hem bij de poten vasthoudend, naar Sjaaks café, waar hij de deur openbonst en rappe Peerke het monster een haal geeft, zodat het bloed uit zijn kop stroomt en de knecht van de \"Beese\" (een boerderij uit de omgeving) er staat, die meteen wegrent, waarna men van de weerwolf niet meer hoorde.","half":"bottom","code":"SINSAG 0801"},"home":"3-1"},{"id":"c11","story_id":"CJ008111","role":"distractor","render":{"description":"Opeens wordt hij gebeten door een jongen in zijn schouder gebeten. Als hij hem vraagt waarom hij bijt, hinnikt de man als een paard. De volgende dag staan er grote indrukken van tanden in het vel. De jongen is één van zeven broers.","half":"bottom","code":"SINSAG 0804"},"home":"3-1"},{"id":"c12","story_id":"CJ039817","role":"distractor","render":{"description":"Bij terugkomst hangen rode draden van de zakdoek tussen zijn tanden. Hij bekent een weerwolf te zijn die af en toe iets moet verscheuren, en had om een zakdoek gevraagd om haar niet te verscheuren.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"},{"id":"c13","story_id":"GENDT028","role":"bottom","render":{"description":"weerwolf is. Toen hij weer een keer vroeg weg wilde lieten ze hem niet gaan. Ze hielden hem net zo lang vast tot er een wolvenvel door de schoorsteen in het vuur viel en verbrandde. Toen was de man verlost.","half":"bottom","code":"SINSAG 0824"},"home":"3-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het bovenste stuk breekt midden in een zin af. Het onderste maakt hem af.","Het nummer is SINSAG 0824. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c13"},"on_success":{"fuse":["c1","c13"],"stack":["c1","c13"]},"found_card":{"card":"c13"}},{"id":"3-2","type":"P3","difficulty":1.0563,"rank":0.462,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"LINSSEN007605","role":"member","render":{"description":"Jongen kan zich in weerwolf veranderen; na bloed trekken uit wolfshond verschijnt de gedaante van de jongen.","place":"Leveroy","prov":"L.","year":1964,"code":null,"initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208819","original":"Weerwolf. Een jongen bezat de macht om zich in een weerwolf te kunnen veranderen. Hij had verkering. Op zekere dag was hij met zijn aanstaande naar de kermis gegaan. In het struikgewas langs de weg gaf hij voor zijn behoefte te moeten doen. Tegen zijn verloofde zei hij, dat ze niet moest schrikken als er plotseling een wolf of een hond voorbij kwam. Het meisje werd bang, liep door en begaf zich naar een café, waar ze geheel onthutst aankwam. Nauwelijks was ze binnen of een wolfshond ging liggen onder de tafel, waaraan zij zat. Een van de aanwezigen had kwade vermoedens over het dier. Wanneer het een weerwolf was, zou hij nadat hem \"bloed\" getrokken was, weer een menselijke gedaante aannemen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"ENGELS003711","role":"member","render":{"description":"Na gevecht met een weerwolf blijkt het een bekende te zijn.","place":"Blerick","prov":"L.","year":1965,"code":null,"initials":"G.G.E.","url":"https://www.verhalenbank.nl/items/show/210804","original":"Weerwolven:\nEen man, die ’s avonds laat door een weerwolf werd besprongen, was hem te gauw af, door zich bliksemsnel om te draaien. Hij kreeg hem er onder. Het bleek een goede bekende van hem te zijn.\n\nGeen omzetting in dialect van het verhaal door Engels.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c3","story_id":"GENDT088","role":"intruder","render":{"description":"Een vrouw komt 's avonds een molenaarsknecht tegen die een weerwolf achter zich aan heeft lopen. De man ziet hem niet en de wolf verdwijnt. Het spookt op die plek.","place":"Gendt","prov":"Gld.","year":1965,"code":null,"initials":"M.H.D.","url":"https://www.verhalenbank.nl/items/show/49723","original":"Ik kwam soaves es ’n keer Jans, de möldersknecht van Hoogveld, tège. Achter ’m liep ’n lillek dier. ’t Leek ’n werwolf. Hé’j had grote klauwe en gloeiende oge. Ik zèj: “Wa hè gé’j dor toch bé’j ou, Jans?” Hé’j zej:“Ik heb niks bé’j mien”. En toe was er ok niks mer. Da gebeurde op ten hoek bé’j de meule. De minse zèje, dat ’t dor altied spokte.","lang":"Gendts (Achterhoeks)","front":"original","uncatalogued":true},"home":"cab:4"},{"id":"c4","story_id":"LINSSEN008310","role":"member","render":{"description":"Na verwonden van weerwolf die op rug wil springen, verdwijnt weerwolf.","place":"Posterholt","prov":"L.","year":1965,"code":null,"initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208887","original":"Weerwolf Een jongeman uit de buurtschap Holst had kennis met een meisje uit de buurtschap Paalder (st. Odilienberg). Meermalen had hij over een grote afstand de weerwolf moeten dragen. Hij had bij anderen raad gevraagd, wat hij daartegen kon doen. Men had hem aangeraden een snijmes (groot breed mes, ongeveer 6o cm lang en 1o cm breed , om stro te snijden met aan beide kanten een houten handvat.) op de rug te binden met de scherpe kant naar achteren gericht. Zo gezegd, zo gedaan. De eerstvolgende keer dat de weerwolf hem weer besprong liet deze een rauwe kreet horen, vluchtte weg en nooit meer had de man last van hem gehad.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een spook.","De kaart over Gendt hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":4},"on_success":{"trail_note":1,"unlock_cabinet":4,"stack":["c1","c2","c4"]}},{"id":"3-3","type":"R3","difficulty":1.0236,"rank":0.3077,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ044011","role":"door","render":{"description":"Een van zeven zonen is een weerwolf. Men moet nooit ruzie krijgen met een weerwolf, want dan maakt hij je dood. \nEen meisje naaide altijd bij andere mensen. Haar vrijer vroeg haar eens om een zakdoek. Ze gaf het hem, en buiten verscheurde hij het ding helemaal. Daarna was hij weer normaal. Hij bleek een weerwolf te zijn. Toen heeft het meisje het uitgemaakt.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0823","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24049","original":"Ien fan sawn soannen wie in wjerwolf. As in wjerwolf jin kriget, makket er jin dea, seinen se froeger tsjin ús. Men mat der noait rûzje mei krije, sei in muoike yn 'e Westerein, dan pakke se jo.\nMyn wiif hat in kammeraetske hawn, dy naeide altyd by oare minsken. Dy hie forkearing mei in feint.\nOp in kear wie er by har, doe frege er har om har bûsdoek. Hja hie him de bûsdoek jown, mar doe hied er dy bûsdoek yn alle moster forskuord bûtendoar.\nLetter wie er wer goed west, mar 't is wol útrekke tusken dy beiden. Hwant hy wie in wjerwolf.\nHja hat it sels oan myn wiif forteld. Dat kammeraetske wenne oan it Wyldpaed.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"HOL001024","role":"card","render":{"description":"Mensen die weerwolven niet aanraken; man die aan het weerwolven is, is op twee plaatsen tegelijk; weerwolven hebben vel om.","place":"Opheusden","prov":"Gld.","year":1962,"code":null,"initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/209732","original":"Gaart en Stoffel van Brenk konden weerwolven. Als deze en ook andere personen daarmee bezig waren, moest men ze niet “omlegge” op het bed, want dan ging het mis met hen. Mensen zagen \"Stomp\" onder de noteboom liggen, maar ook lag hij thuis op bed. Hij was toen aan het weerwolven. Weerwolven hadden een vel om.","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c3","story_id":"VVUNL049","role":"card","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":"SINSAG 0824","initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"KOOIJMAN1182","role":"card","render":{"description":"Er woonde vroeger in Blokland een vrouw en die beweerde dat ze iedere avond de weerwolf buiten tekeer hoorde gaan tussen half elf en twaalf uur.","place":"Blokland","prov":"Utr.","year":1963,"code":"SINSAG 0804","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72678","original":"De weerwolf, de weerwolf. Nou je 't zegt. D'r woonde vroeger in Blokland een vrouw. Die woonde daar op d'r eige alleen. En die vrouw die beweerde, ze hoorde iedere avond de weerwolf buite tekeergaan. Iedere avond tusse half elf en twaalf uur. Ze sloot alles d'r voor af.","lang":"Utrechts","front":"description"},"home":"3-3"},{"id":"c5","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c1","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c2"},"stack":["c2","c3","c4","c5"]}}]},{"id":4,"label":"Spoken","digit":2,"drawers":[{"id":"4-1","type":"P6","difficulty":3.2977,"rank":0.8682,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"VODA_035_18","role":"clip1","render":{"description":"Drie “ouwe jonkheden” (ongetrouwd gebleven boerendochters) zien ’s avonds laat als ze naar huis lopen een doodskist op de dijk staan. Als ze er onderlangs de dijk aan voorbij willen lopen, beweegt de kist en gaat ook van de dijk af. Als de vrouwen de dijk weer op gaan, komt de kist ook de dijk weer op. Uiteindelijk gaat de kist met een knal in blauwe rook en vlammen op.","place":"Terneuzen","prov":"Zl.","year":1971,"code":"SINSAG 0478","initials":"H.E./J.B.","url":"https://www.verhalenbank.nl/items/show/132032","original":"Jao, da kan ‘k nog wel wat vertel’n [geblader] en da gaot dan over ouwe jonkheden. Ouwe jonkheden in de knel.\nDa’s zo rond achttiennegentig over vier jonkheden, ouwe jonkheden noem’n we da, in de buurte. Je weet wel wa da betekende, meneer. Da waoren boerendochters zo van tegen de veertig die ongetrouwd gebleven waren.\nOp een avond tussen kerstdag en nieuwejaar hadden ze bie een van hudder ’s avonds een gezelligen avond deurgebracht me gezelschapsspelletje. ’t Ouwe pachtspel. Dat wuurd dikwijls gespeeld me bruune boon’n. …","lang":"Standaardnederlands; Zeeuws","front":"description"},"home":"4-1"},{"id":"c2","story_id":"CJ106101","role":"clip2","render":{"description":"Man zag eens op een avond een vage gestalte die hij voor een bekende aanzag, toen hij dichterbij wou komen was het weg. Twee weken later stierf de vrouw van diezelfde bekende.","place":"Feanwâlden","prov":"Fr.","year":1974,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37731","original":"Yn Burgum, tichte by de Simmerdyk, seach ik in wazige figuur. It wie de gestalte fan in minske, mar ik koe it gesicht net sjen. It biweegde, mar it roan net. It sweefde. De earms hâldde it by de siden lâns. Sa glied it oer 't lân. Ik seach der nei. Bang wie 'k net. Ik woe der hinne, mar doe't ik der by wie, wie 't ynienen fuort. Ik seach it oan foar Jehannes, dy't dêr tichteby wenne. 't Wie sa'n 1.80 m. lang en griis.\n14 dagen letter is Saekje, Jehannes syn frou, stoarn. Ik freegje my wolris ôf: kin it de geast fan Jehannes west ha?","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c3","story_id":"VODA_035_13","role":"clip3","render":{"description":"Een man werd in het schemerdonker achtervolgd door een wezen dat geen hond en geen kat was. Plots sprong het wezen op de schouders van de man. De man moest het wezen drie-, vierhonderd meter meedragen. Daarna liet het wezen los en verdween brullend in het water. Het was de Ossaart.","place":"Terneuzen","prov":"Zl.","year":1971,"code":"SINSAG 0252","initials":"H.E./J.B.","url":"https://www.verhalenbank.nl/items/show/132027","original":"Lang geleden, misschien achttienzestig, achttienzeventig, woonde op Hengstdijk ‘ne zekere Charrel de Jong. Zijn stee lag kort bij ’t dörp. Maar hij had ook ’n stuk land liggen in de Pauluspolder en da was nogal een end van z’n boerderij af.\nOp ‘nen avond, zo tegen schemerdonker, komt hij terug van z’n land in de Pauluspolder en loopt hij over ’t smalle pad da langs de Vogel voert. Hier en daor ‘nen bosken of hoog struikgewas, aan de waterkanten hoog riet. Ah enfin, hij he nie veel uitzicht.\nAchter zich hoort hij wa ritselen in ’t riet en as ie zich omdraoit da ziet hij da ‘ne vreemd dink hem achterna loopt. ’t Is geen hond, ’t is geen kat, maor wa ’t dan wel is, da kan hij nie achter koom’n. Hij schopt ernaar en even verdwijnt ‘t. …","lang":"Standaardnederlands; Zeeuws","front":"description"},"home":"4-1"},{"id":"c4","story_id":"CJ118005","role":"inside","render":{"description":"Twee advocaten zijn van de duivel bezeten en worden door de duivelbanner vastgezet in een cirkel op de grond. De twee advocaten kunnen nooit uit de cirkel komen en blijven op die plaats rondspoken. Het stuk land heet sindsdien 'Advocatenland'.","place":"Garyp","prov":"Fr.","year":1979,"code":"SINSAG 0410","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/31500","original":"Yn Beetstersweach wennen twa advokaten. Dy wienen fan 'e duvel biseten en dienen folle kwea. Der wie in duvelbander - guon biweare dat it Piter Poes fan de Sumarreheide wie - dy gong mei de boerewein nei de Sweach ta en krige dy beide mannen by him op 'e wein. Twa grouwe gudzen roannen der foar.\nDy twa hynders switten ôfgryslik doe't dy beide advokaten op 'e wein wienen. Hja woenen der graech ôf, en dat prebearren se ek hyltyd, mar dat slagge net, hwant de duvelbanner hie har yn 'e macht.\nDoe rieden se hiel fier fuort, nei in stik lân achter yn 'e Earnewarren, tsjin 't Krúswetter oan. Dêr hat dy duvelbander in sirkel makke, dêr moesten se binnen bliuwe. …","lang":"Fries (Woudfries)","front":"original","note":"Deze bewaar ik apart."},"home":"4-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 3.","3 — 2 — 3."],"lock":{"kind":"number3","salt":"222e7416a6a8c788","accepted_hashes":["b82c9201a000d29d883fb536bf59a116e10e54f5936e89b058420aa55b72d30f"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.3656,"rank":1.0259,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ053402","role":"member","render":{"description":"Het komt wel eens voor dat een dode geen rust kan vinden omdat een aan hem gedane belofte niet nagekomen is. Als de dominee de dode aanspreekt op zijn onvervulde wens en die wens wordt alsnog vervult, vindt de dode rust. Als de dode nog iets overhandigd moet worden, moet je dat in een zakdoek bij elkaar rollen en de punt van de zakdoek vasthouden. Als je dit niet op die manier doet, schroeit je vel eraf.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25362","original":"It gebeurt soms wol us, dat ien dy't to hôf brocht is de rêst net fynt. Dan komt er wer. Meastal mat er dan hwat ha. De doomny freget him dan wol faek hwer't er forlet fan hat. Dan neamt er dat.\nAs men him dat jowt komt er net wer.\nMar men mat goed oppasse hoe't men it him jowt. Men mat it yn in bûsdoek byelkoar rolje en in tippe fan 'e bûsdoek fêsthâlde. Sa mat men it him jaen. Oars skroeit it fel der ôf. De bûsdoek skroeit nou.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"CBOEK305","role":"intruder","render":{"description":"Een andere spookgeschiedenis vertelt over een witgesluierde dame die tussen twaalf en een uur door de muur heen komt. Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","place":"Driebergen-Rijsenburg","prov":"Utr.","year":1892,"code":null,"initials":"M.R.v.d.V.","url":"https://www.verhalenbank.nl/items/show/34810","original":"Een Spookgeschiedenis\nEen spookgeschiedenis zooals deze is er nog een, waarin eene geheimzinnige witgesluierde Dame het spook is; welke eveneens tusschen 12 en 1 uur komt, maar door den muur heen in de slaapkamer en roept, (wanneer zij iemand in de kamer ziet, welke het spook dooden wil), met een holle, nare grafstem: \"Wie stoort hier mijn rust?\" Daarop loopt zij toornig op den bevenden man toe en draait hem den hals om; daarna verdwijnt zij weer door den muur, alhoewel er geen deur in is. Nu durft niemand meer te wagen op het kasteel een nacht te slapen; totdat er eindelijk een moedige sterken man komt, op 't slot des nachts gaat en de witte Dame voor altijd verdelgt...\n(Breedvoerig ken ik deze historie niet meer.)","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c3","story_id":"CJ111728","role":"member","render":{"description":"Als overledenen na hun dood blijven ronddolen, kunnen ze geen rust vinden omdat ze iets uitgehaald hebben of omdat een belofte aan hen gedaan niet nagekomen is. Ook de zielen van vermoorde mensen dolen 's nachts rond. Een man die zijn vrouw bij haar leven slecht behandelde, wordt na de dood van zijn vrouw voortdurend lastiggevallen door haar geest.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29939","original":"Soms dwaelden der minsken op 'e paden om dy't al stoarn wienen. Dy hienen hwat útheefd en koenen de rêst net fine. Of se hienen noch in bigearte, dy't earst yn forfulling gean moest.\nEk guon dy't formoarde wienen dwelmen nachts om. Yn Kollumersweach wie in wiif stoarn, dy har man hie har min bihandele. Nei har dea kaem se hyltyd wer by dy man. Soms roun se njonken him lâns. Hy koe har net wer kwyt wurde.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"CJ002908","role":"member","render":{"description":"Een vrouw sterft in Egypte en ze bezoekt dagelijks haar man. De man haalt de dominee erbij en de vrouw zegt tegen de dominee wat ze begeert. De man doet wat de vrouw wil en sindsien spookt het er niet meer.","place":"Kollumersweach","prov":"Fr.","year":1950,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/15731","original":"Yn Egypte wenne in man, dy syn wyfke forstoar, mar nei har dea kom se alle dagen by him. Hy helle de dûmny der by, dy't har oanspruts en frege hwat se bigearde. Oan dy dûmny joech se har bigearte to witen. De man foldie oan dy bigearte en it spoekjen wie dien.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Driebergen-Rijsenburg hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":2},"on_success":{"trail_note":2,"unlock_cabinet":2,"stack":["c1","c3","c4"]}},{"id":"4-3","type":"R4","difficulty":1.1767,"rank":0.5417,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"LYST113","role":"top","render":{"description":"De vrouw van de concierge van het stadhuis overlijdt. Als de dienstbode van het huis naar de kelder gaat om de boter te spitten, ziet ze de overleden vrouw bij de boterton staan.","place":"Leiden","prov":"Z.-H.","year":1957,"code":"SINSAG 0475","initials":"C.A.A.d.J.","url":"https://www.verhalenbank.nl/items/show/13314","half":"top"},"home":"4-3"},{"id":"c2","story_id":"CJ081008","role":"half","render":{"description":"Ze zagen daar langs de kant een reus, die wel twee keer zo groot was als een normaal mens. Een groot kleed wapperde om hem heen, verder stond hij helemaal stil. Het was een spook.","half":"bottom","code":"SINSAG 0475"},"home":"4-3"},{"id":"c3","story_id":"CJ030711","role":"half","render":{"description":"Een van de familieleden krijgt eens uit het niets een hand toegestoken. Ook de schuurdeuren waaien vanzelf open.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c4","story_id":"CJ0286A01","role":"half","render":{"description":"Als de dominee vraagt wat haar onvervulde wens is, zegt ze dat er in het huis geld verstopt ligt dat aan de armen toebehoort. Pas als de armen hun geld terugkrijgen, zal haar ziel rust kunnen vinden. Haar wens wordt vervuld en de vrouw is nooit meer komen spoken.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c5","story_id":"CJ032603","role":"half","render":{"description":"De geest van zijn overleden vrouw wil wraak nemen. De dominee moet eraan te pas komen om het spook te verjagen: hij raakt het spook met een witte zakdoek aan en spreekt de bezweringsformule 'Ga jij duivel in de gedaante van een vrouw weg!' uit.","half":"bottom","code":"SINSAG 0434"},"home":"4-3"},{"id":"c6","story_id":"LYST113","role":"bottom","render":{"description":"Ze vertelt het aan een oudere dienstbode, maar die gelooft haar niet. Op een dag zien de twee dienstboden beide de verschijning van hun overleden mevrouw. Ze roepen de concierge erbij. Op het moment dat de concierge in de kelder komt kijken, is de verschijning weer verdwenen. De boter die gespit moest worden is helemaal verpest; het is net modder geworden.","half":"bottom","code":"SINSAG 0475","stain":"twee"},"home":"4-3"},{"id":"c7","story_id":"CJ0286A05","role":"half","render":{"description":"Als het jongetje hem langs de schuur volgt, verdwijnt de man even plotseling als hij verschenen is. De hulp van een roomse man wordt ingeschakeld, maar ook hij kan de man niet bereiken. Het is een spookverschijning.","half":"bottom","code":"SINSAG 0475"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘boter’ opnieuw.","Het nummer is SINSAG 0475. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c6","object":"typewriter"},"on_success":{"fuse":["c1","c6"],"type_line":"Verteller: de vorige assistent.","digit":{"value":2,"card":"c1","word":"twee","stained":"c6"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
